static void add(void) {
  int i, j, k, m;
  const int gp0 = grid_points[0];
  const int gp1 = grid_points[1];
  const int gp2 = grid_points[2];

  for (i = 1; i < gp0 - 1; i++) {
    for (j = 1; j < gp1 - 1; j++) {
      for (k = 1; k < gp2 - 1; k++) {
#if defined(__riscv_vector) && defined(__GNUC__)
        double *up = &u[i][j][k][0];
        double *rp = &rhs[i][j][k][0];
        __asm__ volatile(
          "li t0, 5\n\t"
          "vsetvli t0, t0, e64, m1, ta, ma\n\t"
          "vle64.v v0, (%0)\n\t"
          "vle64.v v1, (%1)\n\t"
          "vfadd.vv v0, v0, v1\n\t"
          "vse64.v v0, (%0)\n\t"
          :
          : "r"(up), "r"(rp)
          : "t0", "memory", "v0", "v1");
#else
        for (m = 0; m < 5; m++) {
          u[i][j][k][m] = u[i][j][k][m] + rhs[i][j][k][m];
        }
#endif
      }
    }
  }
}

