static void initialize(void) {
{
  int i, j, k, m;
  double xi, eta, zeta, Pface[2][3][5], temp[5];
  const int gp0 = grid_points[0];
  const int gp1 = grid_points[1];
  const int gp2 = grid_points[2];

  for (i = 0; i < IMAX; i++) {
    for (j = 0; j < IMAX; j++) {
      for (k = 0; k < IMAX; k++) {
        double *uk = &u[i][j][k][0];
        for (m = 0; m < 5; m++) {
          uk[m] = 1.0;
        }
      }
    }
  }

  for (i = 0; i < gp0; i++) {
    xi = (double)i * dnxm1;
    {
      const double one_minus_xi = 1.0 - xi;

      for (j = 0; j < gp1; j++) {
        eta = (double)j * dnym1;
        {
          const double one_minus_eta = 1.0 - eta;

          for (k = 0; k < gp2; k++) {
            zeta = (double)k * dnzm1;
            const double one_minus_zeta = 1.0 - zeta;
            double *uk = &u[i][j][k][0];

            exact_solution(0.0, eta, zeta, &Pface[0][0][0]);
            exact_solution(1.0, eta, zeta, &Pface[1][0][0]);
            exact_solution(xi, 0.0, zeta, &Pface[0][1][0]);
            exact_solution(xi, 1.0, zeta, &Pface[1][1][0]);
            exact_solution(xi, eta, 0.0, &Pface[0][2][0]);
            exact_solution(xi, eta, 1.0, &Pface[1][2][0]);

            for (m = 0; m < 5; m++) {
              const double Pxi   = xi   * Pface[1][0][m] + one_minus_xi   * Pface[0][0][m];
              const double Peta  = eta  * Pface[1][1][m] + one_minus_eta  * Pface[0][1][m];
              const double Pzeta = zeta * Pface[1][2][m] + one_minus_zeta * Pface[0][2][m];

              uk[m] = Pxi + Peta + Pzeta
                    - Pxi * Peta - Pxi * Pzeta - Peta * Pzeta
                    + Pxi * Peta * Pzeta;
            }
          }
        }
      }
    }
  }

  i = 0;
  xi = 0.0;
  for (j = 0; j < gp1; j++) {
    eta = (double)j * dnym1;
    for (k = 0; k < gp2; k++) {
      zeta = (double)k * dnzm1;
      exact_solution(xi, eta, zeta, temp);
      for (m = 0; m < 5; m++) {
        u[i][j][k][m] = temp[m];
      }
    }
  }

  i = gp0 - 1;
  xi = 1.0;
  for (j = 0; j < gp1; j++) {
    eta = (double)j * dnym1;
    for (k = 0; k < gp2; k++) {
      zeta = (double)k * dnzm1;
      exact_solution(xi, eta, zeta, temp);
      for (m = 0; m < 5; m++) {
        u[i][j][k][m] = temp[m];
      }
    }
  }

  j = 0;
  eta = 0.0;
  for (i = 0; i < gp0; i++) {
    xi = (double)i * dnxm1;
    for (k = 0; k < gp2; k++) {
      zeta = (double)k * dnzm1;
      exact_solution(xi, eta, zeta, temp);
      for (m = 0; m < 5; m++) {
        u[i][j][k][m] = temp[m];
      }
    }
  }

  j = gp1 - 1;
  eta = 1.0;
  for (i = 0; i < gp0; i++) {
    xi = (double)i * dnxm1;
    for (k = 0; k < gp2; k++) {
      zeta = (double)k * dnzm1;
      exact_solution(xi, eta, zeta, temp);
      for (m = 0; m < 5; m++) {
        u[i][j][k][m] = temp[m];
      }
    }
  }

  k = 0;
  zeta = 0.0;
  for (i = 0; i < gp0; i++) {
    xi = (double)i * dnxm1;
    for (j = 0; j < gp1; j++) {
      eta = (double)j * dnym1;
      exact_solution(xi, eta, zeta, temp);
      for (m = 0; m < 5; m++) {
        u[i][j][k][m] = temp[m];
      }
    }
  }

  k = gp2 - 1;
  zeta = 1.0;
  for (i = 0; i < gp0; i++) {
    xi = (double)i * dnxm1;
    for (j = 0; j < gp1; j++) {
      eta = (double)j * dnym1;
      exact_solution(xi, eta, zeta, temp);
      for (m = 0; m < 5; m++) {
        u[i][j][k][m] = temp[m];
      }
    }
  }
}
}

static void lhsx(void) {

  int i, j, k;
  const int gp0 = grid_points[0];
  const int gp1 = grid_points[1];
  const int gp2 = grid_points[2];

  const double cc2h = c2 * 0.50;
  const double c2mc = 2.0 - c2;
  const double hc2  = 0.50 * c2;
  const double a1   = con43 * c3c4;
  const double a2   = c3c4 - c1345;
  const double a3   = con43 * c3c4 - c1345;

  for (j = 1; j < gp1 - 1; j++) {
    for (k = 1; k < gp2 - 1; k++) {
      for (i = 0; i < gp0; i++) {
        double (*uijk)[5] = &u[i][j][k];
        double (*fj)[5] = fjac[i][j][k];
        double (*nj)[5] = njac[i][j][k];

        const double u0 = (*uijk)[0];
        const double u1 = (*uijk)[1];
        const double u2 = (*uijk)[2];
        const double u3 = (*uijk)[3];
        const double u4 = (*uijk)[4];

        const double u1_2 = u1 * u1;
        const double u2_2 = u2 * u2;
        const double u3_2 = u3 * u3;
        const double sumsq = u1_2 + u2_2 + u3_2;

        tmp1 = 1.0 / u0;
        tmp2 = tmp1 * tmp1;
        tmp3 = tmp1 * tmp2;

        fj[0][0] = 0.0;
        fj[0][1] = 1.0;
        fj[0][2] = 0.0;
        fj[0][3] = 0.0;
        fj[0][4] = 0.0;

        fj[1][0] = -(u1 * tmp2 * u1) + cc2h * sumsq * tmp2;
        fj[1][1] = c2mc * (u1 / u0);
        fj[1][2] = -c2 * (u2 * tmp1);
        fj[1][3] = -c2 * (u3 * tmp1);
        fj[1][4] = c2;

        fj[2][0] = -(u1 * u2) * tmp2;
        fj[2][1] = u2 * tmp1;
        fj[2][2] = u1 * tmp1;
        fj[2][3] = 0.0;
        fj[2][4] = 0.0;

        fj[3][0] = -(u1 * u3) * tmp2;
        fj[3][1] = u3 * tmp1;
        fj[3][2] = 0.0;
        fj[3][3] = u1 * tmp1;
        fj[3][4] = 0.0;

        fj[4][0] = (c2 * sumsq * tmp2 - c1 * (u4 * tmp1)) * (u1 * tmp1);
        fj[4][1] = c1 * u4 * tmp1
                 - hc2 * (3.0 * u1_2 + u2_2 + u3_2) * tmp2;
        fj[4][2] = -c2 * (u2 * u1) * tmp2;
        fj[4][3] = -c2 * (u3 * u1) * tmp2;
        fj[4][4] = c1 * (u1 * tmp1);

        nj[0][0] = 0.0;
        nj[0][1] = 0.0;
        nj[0][2] = 0.0;
        nj[0][3] = 0.0;
        nj[0][4] = 0.0;

        nj[1][0] = -a1 * tmp2 * u1;
        nj[1][1] =  a1 * tmp1;
        nj[1][2] =  0.0;
        nj[1][3] =  0.0;
        nj[1][4] =  0.0;

        nj[2][0] = -c3c4 * tmp2 * u2;
        nj[2][1] =  0.0;
        nj[2][2] =  c3c4 * tmp1;
        nj[2][3] =  0.0;
        nj[2][4] =  0.0;

        nj[3][0] = -c3c4 * tmp2 * u3;
        nj[3][1] =  0.0;
        nj[3][2] =  0.0;
        nj[3][3] =  c3c4 * tmp1;
        nj[3][4] =  0.0;

        nj[4][0] = -a3 * tmp3 * (pow2(u1))
                 -  a2 * tmp3 * (pow2(u2))
                 -  a2 * tmp3 * (pow2(u3))
                 -  c1345 * tmp2 * u4;
        nj[4][1] =  a3 * tmp2 * u1;
        nj[4][2] =  a2 * tmp2 * u2;
        nj[4][3] =  a2 * tmp2 * u3;
        nj[4][4] =  c1345 * tmp1;
      }

      for (i = 1; i < gp0 - 1; i++) {
        double (*lhsaa)[5] = lhs[i][j][k][AA];
        double (*lhsbb)[5] = lhs[i][j][k][BB];
        double (*lhscc)[5] = lhs[i][j][k][CC];

        double (*fjm)[5] = fjac[i - 1][j][k];
        double (*njm)[5] = njac[i - 1][j][k];
        double (*nj0)[5] = njac[i][j][k];
        double (*fjp)[5] = fjac[i + 1][j][k];
        double (*njp)[5] = njac[i + 1][j][k];

        tmp1 = dt * tx1;
        tmp2 = dt * tx2;

        lhsaa[0][0] = -tmp2 * fjm[0][0] - tmp1 * njm[0][0] - tmp1 * dx1;
        lhsaa[0][1] = -tmp2 * fjm[0][1] - tmp1 * njm[0][1];
        lhsaa[0][2] = -tmp2 * fjm[0][2] - tmp1 * njm[0][2];
        lhsaa[0][3] = -tmp2 * fjm[0][3] - tmp1 * njm[0][3];
        lhsaa[0][4] = -tmp2 * fjm[0][4] - tmp1 * njm[0][4];

        lhsaa[1][0] = -tmp2 * fjm[1][0] - tmp1 * njm[1][0];
        lhsaa[1][1] = -tmp2 * fjm[1][1] - tmp1 * njm[1][1] - tmp1 * dx2;
        lhsaa[1][2] = -tmp2 * fjm[1][2] - tmp1 * njm[1][2];
        lhsaa[1][3] = -tmp2 * fjm[1][3] - tmp1 * njm[1][3];
        lhsaa[1][4] = -tmp2 * fjm[1][4] - tmp1 * njm[1][4];

        lhsaa[2][0] = -tmp2 * fjm[2][0] - tmp1 * njm[2][0];
        lhsaa[2][1] = -tmp2 * fjm[2][1] - tmp1 * njm[2][1];
        lhsaa[2][2] = -tmp2 * fjm[2][2] - tmp1 * njm[2][2] - tmp1 * dx3;
        lhsaa[2][3] = -tmp2 * fjm[2][3] - tmp1 * njm[2][3];
        lhsaa[2][4] = -tmp2 * fjm[2][4] - tmp1 * njm[2][4];

        lhsaa[3][0] = -tmp2 * fjm[3][0] - tmp1 * njm[3][0];
        lhsaa[3][1] = -tmp2 * fjm[3][1] - tmp1 * njm[3][1];
        lhsaa[3][2] = -tmp2 * fjm[3][2] - tmp1 * njm[3][2];
        lhsaa[3][3] = -tmp2 * fjm[3][3] - tmp1 * njm[3][3] - tmp1 * dx4;
        lhsaa[3][4] = -tmp2 * fjm[3][4] - tmp1 * njm[3][4];

        lhsaa[4][0] = -tmp2 * fjm[4][0] - tmp1 * njm[4][0];
        lhsaa[4][1] = -tmp2 * fjm[4][1] - tmp1 * njm[4][1];
        lhsaa[4][2] = -tmp2 * fjm[4][2] - tmp1 * njm[4][2];
        lhsaa[4][3] = -tmp2 * fjm[4][3] - tmp1 * njm[4][3];
        lhsaa[4][4] = -tmp2 * fjm[4][4] - tmp1 * njm[4][4] - tmp1 * dx5;

        lhsbb[0][0] = 1.0 + tmp1 * 2.0 * nj0[0][0] + tmp1 * 2.0 * dx1;
        lhsbb[0][1] = tmp1 * 2.0 * nj0[0][1];
        lhsbb[0][2] = tmp1 * 2.0 * nj0[0][2];
        lhsbb[0][3] = tmp1 * 2.0 * nj0[0][3];
        lhsbb[0][4] = tmp1 * 2.0 * nj0[0][4];

        lhsbb[1][0] = tmp1 * 2.0 * nj0[1][0];
        lhsbb[1][1] = 1.0 + tmp1 * 2.0 * nj0[1][1] + tmp1 * 2.0 * dx2;
        lhsbb[1][2] = tmp1 * 2.0 * nj0[1][2];
        lhsbb[1][3] = tmp1 * 2.0 * nj0[1][3];
        lhsbb[1][4] = tmp1 * 2.0 * nj0[1][4];

        lhsbb[2][0] = tmp1 * 2.0 * nj0[2][0];
        lhsbb[2][1] = tmp1 * 2.0 * nj0[2][1];
        lhsbb[2][2] = 1.0 + tmp1 * 2.0 * nj0[2][2] + tmp1 * 2.0 * dx3;
        lhsbb[2][3] = tmp1 * 2.0 * nj0[2][3];
        lhsbb[2][4] = tmp1 * 2.0 * nj0[2][4];

        lhsbb[3][0] = tmp1 * 2.0 * nj0[3][0];
        lhsbb[3][1] = tmp1 * 2.0 * nj0[3][1];
        lhsbb[3][2] = tmp1 * 2.0 * nj0[3][2];
        lhsbb[3][3] = 1.0 + tmp1 * 2.0 * nj0[3][3] + tmp1 * 2.0 * dx4;
        lhsbb[3][4] = tmp1 * 2.0 * nj0[3][4];

        lhsbb[4][0] = tmp1 * 2.0 * nj0[4][0];
        lhsbb[4][1] = tmp1 * 2.0 * nj0[4][1];
        lhsbb[4][2] = tmp1 * 2.0 * nj0[4][2];
        lhsbb[4][3] = tmp1 * 2.0 * nj0[4][3];
        lhsbb[4][4] = 1.0 + tmp1 * 2.0 * nj0[4][4] + tmp1 * 2.0 * dx5;

        lhscc[0][0] = tmp2 * fjp[0][0] - tmp1 * njp[0][0] - tmp1 * dx1;
        lhscc[0][1] = tmp2 * fjp[0][1] - tmp1 * njp[0][1];
        lhscc[0][2] = tmp2 * fjp[0][2] - tmp1 * njp[0][2];
        lhscc[0][3] = tmp2 * fjp[0][3] - tmp1 * njp[0][3];
        lhscc[0][4] = tmp2 * fjp[0][4] - tmp1 * njp[0][4];

        lhscc[1][0] = tmp2 * fjp[1][0] - tmp1 * njp[1][0];
        lhscc[1][1] = tmp2 * fjp[1][1] - tmp1 * njp[1][1] - tmp1 * dx2;
        lhscc[1][2] = tmp2 * fjp[1][2] - tmp1 * njp[1][2];
        lhscc[1][3] = tmp2 * fjp[1][3] - tmp1 * njp[1][3];
        lhscc[1][4] = tmp2 * fjp[1][4] - tmp1 * njp[1][4];

        lhscc[2][0] = tmp2 * fjp[2][0] - tmp1 * njp[2][0];
        lhscc[2][1] = tmp2 * fjp[2][1] - tmp1 * njp[2][1];
        lhscc[2][2] = tmp2 * fjp[2][2] - tmp1 * njp[2][2] - tmp1 * dx3;
        lhscc[2][3] = tmp2 * fjp[2][3] - tmp1 * njp[2][3];
        lhscc[2][4] = tmp2 * fjp[2][4] - tmp1 * njp[2][4];

        lhscc[3][0] = tmp2 * fjp[3][0] - tmp1 * njp[3][0];
        lhscc[3][1] = tmp2 * fjp[3][1] - tmp1 * njp[3][1];
        lhscc[3][2] = tmp2 * fjp[3][2] - tmp1 * njp[3][2];
        lhscc[3][3] = tmp2 * fjp[3][3] - tmp1 * njp[3][3] - tmp1 * dx4;
        lhscc[3][4] = tmp2 * fjp[3][4] - tmp1 * njp[3][4];

        lhscc[4][0] = tmp2 * fjp[4][0] - tmp1 * njp[4][0];
        lhscc[4][1] = tmp2 * fjp[4][1] - tmp1 * njp[4][1];
        lhscc[4][2] = tmp2 * fjp[4][2] - tmp1 * njp[4][2];
        lhscc[4][3] = tmp2 * fjp[4][3] - tmp1 * njp[4][3];
        lhscc[4][4] = tmp2 * fjp[4][4] - tmp1 * njp[4][4] - tmp1 * dx5;
      }
    }
  }
}

int main(int argc, char **argv) {
  int niter, step, n3;
  int nthreads = 1;
  double navg, mflops;

  double tmax;
  boolean verified;
  char class;
  FILE *fp;

  printf("\n\n NAS Parallel Benchmarks 3.0 structured OpenMP C version"
         " - BT Benchmark\n\n");

  fp = fopen("inputbt.data", "r");
  if (fp != NULL) {
    printf(" Reading from input file inputbt.data");
    fscanf(fp, "%d", &niter);
    while (fgetc(fp) != '\n')
      ;
    fscanf(fp, "%lg", &dt);
    while (fgetc(fp) != '\n')
      ;
    fscanf(fp, "%d%d%d",
           &grid_points[0], &grid_points[1], &grid_points[2]);
    fclose(fp);
  } else {
    printf(" No input file inputbt.data. Using compiled defaults\n");

    niter = NITER_DEFAULT;
    dt = DT_DEFAULT;
    grid_points[0] = PROBLEM_SIZE;
    grid_points[1] = PROBLEM_SIZE;
    grid_points[2] = PROBLEM_SIZE;
  }

  printf(" Size: %3dx%3dx%3d\n",
         grid_points[0], grid_points[1], grid_points[2]);
  printf(" Iterations: %3d   dt: %10.6f\n", niter, dt);

  if (grid_points[0] > IMAX ||
      grid_points[1] > JMAX ||
      grid_points[2] > KMAX) {
    printf(" %dx%dx%d\n", grid_points[0], grid_points[1], grid_points[2]);
    printf(" Problem size too big for compiled array sizes\n");
    exit(1);
  }

  set_constants();

  initialize();
  lhsinit();
  exact_rhs();

  adi();

  initialize();

  timer_clear(1);
  timer_start(1);

  for (step = 1; step <= niter; step++) {
    if (step == 1 || step % 20 == 0) {
      printf(" Time step %4d\n", step);
    }
    adi();
  }

  {
#if defined(_OPENMP)
    nthreads = omp_get_num_threads();
#endif
  }

  timer_stop(1);
  tmax = timer_read(1);

  verify(niter, &class, &verified);

  {
    const int gp0 = grid_points[0];
    const int gp1 = grid_points[1];
    const int gp2 = grid_points[2];
    n3 = gp0 * gp1 * gp2;
    navg = (gp0 + gp1 + gp2) / 3.0;
  }

  if (tmax != 0.0) {
    const double navg2 = pow2(navg);
    mflops = 1.0e-6 * (double)niter *
             (3478.8 * (double)n3 - 17655.7 * navg2 + 28023.7 * navg) / tmax;
  } else {
    mflops = 0.0;
  }

  c_print_results("BT", class, grid_points[0],
                  grid_points[1], grid_points[2], niter, nthreads,
                  tmax, mflops, "          floating point",
                  verified, NPBVERSION, COMPILETIME, CS1, CS2, CS3, CS4, CS5,
                  CS6, "(none)");
}

