static void conj_grad (
    int colidx[],
    int rowstr[],
    double x[],
    double z[],
    double a[],
    double p[],
    double q[],
    double r[],
    double *rnorm )
{
    static int callcount = 0;
    double d, sum, rho, rho0, alpha, beta;
    int i, j, k;
    int cgit, cgitmax = 25;

    const int ncol = lastcol - firstcol + 1;
    const int nrow = lastrow - firstrow + 1;
    const int nall = naa + 1;

    rho = 0.0;

    {
        for (j = 1; j <= nall; j++) {
            q[j] = 0.0;
            z[j] = 0.0;
            r[j] = x[j];
            p[j] = r[j];
        }

        for (j = 1; j <= ncol; j++) {
            rho = rho + r[j] * r[j];
        }
    }

    for (cgit = 1; cgit <= cgitmax; cgit++) {
        rho0 = rho;
        d = 0.0;
        rho = 0.0;

        {
            for (j = 1; j <= nrow; j++) {
                double sum0 = 0.0;
                int ks = rowstr[j];
                int ke = rowstr[j + 1];
                for (k = ks; k < ke; k++) {
                    sum0 = sum0 + a[k] * p[colidx[k]];
                }
                q[j] = sum0;
            }

            for (j = 1; j <= ncol; j++) {
                d = d + p[j] * q[j];
            }

            alpha = rho0 / d;

            for (j = 1; j <= ncol; j++) {
                double pj = p[j];
                double qj = q[j];
                double rj = r[j] - alpha * qj;
                z[j] = z[j] + alpha * pj;
                r[j] = rj;
                rho = rho + rj * rj;
            }

            beta = rho / rho0;

            for (j = 1; j <= ncol; j++) {
                p[j] = r[j] + beta * p[j];
            }

            callcount++;
        }
    }

    sum = 0.0;

    {
        for (j = 1; j <= nrow; j++) {
            double sum0 = 0.0;
            int ks = rowstr[j];
            int ke = rowstr[j + 1];
            for (k = ks; k < ke; k++) {
                sum0 = sum0 + a[k] * z[colidx[k]];
            }
            r[j] = sum0;
        }

        for (j = 1; j <= ncol; j++) {
            double dj = x[j] - r[j];
            sum = sum + dj * dj;
        }
    }

    (*rnorm) = sqrt(sum);
}

int main(int argc, char **argv) {
    int i, j, k, it;
    int nthreads = 1;
    double zeta;
    double rnorm;
    double norm_temp11;
    double norm_temp12;
    double t, mflops;
    char class;
    boolean verified;
    double zeta_verify_value, epsilon;

    firstrow = 1;
    lastrow  = NA;
    firstcol = 1;
    lastcol  = NA;

    if (NA == 1400 && NONZER == 7 && NITER == 15 && SHIFT == 10.0) {
        class = 'S';
        zeta_verify_value = 8.5971775078648;
    } else if (NA == 7000 && NONZER == 8 && NITER == 15 && SHIFT == 12.0) {
        class = 'W';
        zeta_verify_value = 10.362595087124;
    } else if (NA == 14000 && NONZER == 11 && NITER == 15 && SHIFT == 20.0) {
        class = 'A';
        zeta_verify_value = 17.130235054029;
    } else if (NA == 75000 && NONZER == 13 && NITER == 75 && SHIFT == 60.0) {
        class = 'B';
        zeta_verify_value = 22.712745482631;
    } else if (NA == 150000 && NONZER == 15 && NITER == 75 && SHIFT == 110.0) {
        class = 'C';
        zeta_verify_value = 28.973605592845;
    } else {
        class = 'U';
    }

    printf("\n\n NAS Parallel Benchmarks 3.0 structured OpenMP C version"
           " - CG Benchmark\n");
    printf(" Size: %10d\n", NA);
    printf(" Iterations: %5d\n", NITER);

    naa = NA;
    nzz = NZ;

    tran  = 314159265.0;
    amult = 1220703125.0;
    zeta  = randlc(&tran, amult);

    makea(naa, nzz, a, colidx, rowstr, NONZER,
          firstrow, lastrow, firstcol, lastcol,
          RCOND, arow, acol, aelt, v, iv, SHIFT);

    {
        const int nrows = lastrow - firstrow + 1;
        const int ncols = lastcol - firstcol + 1;

        for (j = 1; j <= nrows; j++) {
            int row_start = rowstr[j];
            int row_end   = rowstr[j + 1];
            for (k = row_start; k < row_end; k++) {
                colidx[k] = colidx[k] - firstcol + 1;
            }
        }

        for (i = 1; i <= NA + 1; i++) {
            x[i] = 1.0;
        }
        for (j = 1; j <= ncols; j++) {
            q[j] = 0.0;
            z[j] = 0.0;
            r[j] = 0.0;
            p[j] = 0.0;
        }
    }

    zeta = 0.0;

    for (it = 1; it <= 1; it++) {
        const int ncols = lastcol - firstcol + 1;

        conj_grad(colidx, rowstr, x, z, a, p, q, r, &rnorm);

        norm_temp11 = 0.0;
        norm_temp12 = 0.0;

        for (j = 1; j <= ncols; j++) {
            double zj = z[j];
            norm_temp11 += x[j] * zj;
            norm_temp12 += zj * zj;
        }

        norm_temp12 = 1.0 / sqrt(norm_temp12);

        for (j = 1; j <= ncols; j++) {
            x[j] = norm_temp12 * z[j];
        }
    }

    for (i = 1; i <= NA + 1; i++) {
        x[i] = 1.0;
    }

    zeta = 0.0;

    timer_clear(1);
    timer_start(1);

    for (it = 1; it <= NITER; it++) {
        const int ncols = lastcol - firstcol + 1;

        conj_grad(colidx, rowstr, x, z, a, p, q, r, &rnorm);

        norm_temp11 = 0.0;
        norm_temp12 = 0.0;

        for (j = 1; j <= ncols; j++) {
            double zj = z[j];
            norm_temp11 += x[j] * zj;
            norm_temp12 += zj * zj;
        }

        norm_temp12 = 1.0 / sqrt(norm_temp12);

        zeta = SHIFT + 1.0 / norm_temp11;

        if (it == 1) {
            printf("   iteration           ||r||                 zeta\n");
        }
        printf("    %5d       %20.14e%20.13e\n", it, rnorm, zeta);

        for (j = 1; j <= ncols; j++) {
            x[j] = norm_temp12 * z[j];
        }
    }

    {
#if defined(_OPENMP)
        nthreads = omp_get_num_threads();
#endif
    }

    timer_stop(1);

    t = timer_read(1);

    printf(" Benchmark completed\n");

    epsilon = 1.0e-10;
    if (class != 'U') {
        if (fabs(zeta - zeta_verify_value) <= epsilon) {
            verified = TRUE;
            printf(" VERIFICATION SUCCESSFUL\n");
            printf(" Zeta is    %20.12e\n", zeta);
            printf(" Error is   %20.12e\n", zeta - zeta_verify_value);
        } else {
            verified = FALSE;
            printf(" VERIFICATION FAILED\n");
            printf(" Zeta                %20.12e\n", zeta);
            printf(" The correct zeta is %20.12e\n", zeta_verify_value);
        }
    } else {
        verified = FALSE;
        printf(" Problem size unknown\n");
        printf(" NO VERIFICATION PERFORMED\n");
    }

    if (t != 0.0) {
        mflops = (2.0 * NITER * NA)
            * (3.0 + (NONZER * (NONZER + 1)) +
               25.0 * (5.0 + (NONZER * (NONZER + 1))) + 3.0)
            / t / 1000000.0;
    } else {
        mflops = 0.0;
    }

    c_print_results("CG", class, NA, 0, 0, NITER, nthreads, t,
                    mflops, "          floating point",
                    verified, NPBVERSION, COMPILETIME,
                    CS1, CS2, CS3, CS4, CS5, CS6, CS7);
}

static void makea(
    int n,
    int nz,
    double a[],
    int colidx[],
    int rowstr[],
    int nonzer,
    int firstrow,
    int lastrow,
    int firstcol,
    int lastcol,
    double rcond,
    int arow[],
    int acol[],
    double aelt[],
    double v[],
    int iv[],
    double shift )
{
    int i, nnza, iouter, ivelt, ivelt1, irow, nzv;
    double size, ratio, scale;
    int jcol;

    size = 1.0;
    ratio = pow(rcond, (1.0 / (double)n));
    nnza = 0;

    {
        int *p = &colidx[n + 1];
        for (i = 1; i <= n; i++) {
            *p++ = 0;
        }
    }

    for (iouter = 1; iouter <= n; iouter++) {
        nzv = nonzer;
        sprnvc(n, nzv, v, iv, &(colidx[0]), &(colidx[n]));
        vecset(n, v, iv, &nzv, iouter, 0.5);

        {
            const int *iv_base = &iv[1];
            const double *v_base = &v[1];
            const int nzv_local = nzv;
            const int firstrow_local = firstrow;
            const int lastrow_local = lastrow;
            const int firstcol_local = firstcol;
            const int lastcol_local = lastcol;

            for (ivelt = 1; ivelt <= nzv_local; ivelt++) {
                jcol = iv_base[ivelt - 1];
                if ((unsigned)(jcol - firstcol_local) <= (unsigned)(lastcol_local - firstcol_local)) {
                    scale = size * v_base[ivelt - 1];

                    {
                        const int *ivp = iv_base;
                        const double *vp = v_base;
                        int count = nzv_local;

                        while (count-- > 0) {
                            irow = *ivp++;
                            if ((unsigned)(irow - firstrow_local) <= (unsigned)(lastrow_local - firstrow_local)) {
                                nnza = nnza + 1;
                                if (nnza > nz) {
                                    printf("Space for matrix elements exceeded in"
                                           " makea\n");
                                    printf("nnza, nzmax = %d, %d\n", nnza, nz);
                                    printf("iouter = %d\n", iouter);
                                    exit(1);
                                }
                                acol[nnza] = jcol;
                                arow[nnza] = irow;
                                aelt[nnza] = (*vp) * scale;
                            }
                            vp++;
                        }
                    }
                }
            }
        }
        size = size * ratio;
    }

    for (i = firstrow; i <= lastrow; i++) {
        if ((unsigned)(i - firstcol) <= (unsigned)(lastcol - firstcol)) {
            iouter = n + i;
            nnza = nnza + 1;
            if (nnza > nz) {
                printf("Space for matrix elements exceeded in makea\n");
                printf("nnza, nzmax = %d, %d\n", nnza, nz);
                printf("iouter = %d\n", iouter);
                exit(1);
            }
            acol[nnza] = i;
            arow[nnza] = i;
            aelt[nnza] = rcond - shift;
        }
    }

    sparse(a, colidx, rowstr, n, arow, acol, aelt,
           firstrow, lastrow, v, &(iv[0]), &(iv[n]), nnza);
}

static void sparse(
    double a[],
    int colidx[],
    int rowstr[],
    int n,
    int arow[],
    int acol[],
    double aelt[],
    int firstrow,
    int lastrow,
    double x[],
    boolean mark[],
    int nzloc[],
    int nnza)

{
    int nrows;
    int i, j, jajp1, nza, k, nzrow;
    double xi;

    nrows = lastrow - firstrow + 1;

#if defined(__riscv_vector) && defined(__has_include)
#if __has_include(<riscv_vector.h>)
#include <riscv_vector.h>
#define SPARSE_USE_RVV 1
#endif
#endif

#if defined(SPARSE_USE_RVV)
    {
        int idx = 1;
        while (idx <= n) {
            size_t vl = __riscv_vsetvl_e32m8((size_t)(n - idx + 1));
            vint32m8_t vz_i32 = __riscv_vmv_v_x_i32m8(0, vl);
            __riscv_vse32_v_i32m8(&rowstr[idx], vz_i32, vl);
            idx += (int)vl;
        }
        idx = 1;
        while (idx <= n) {
            size_t vl = __riscv_vsetvl_e8m8((size_t)(n - idx + 1));
            vuint8m8_t vz_b = __riscv_vmv_v_x_u8m8((uint8_t)FALSE, vl);
            __riscv_vse8_v_u8m8((uint8_t *)&mark[idx], vz_b, vl);
            idx += (int)vl;
        }
    }
#else
    for (j = 1; j <= n; j++) {
        rowstr[j] = 0;
        mark[j] = FALSE;
    }
#endif
    rowstr[n+1] = 0;

    for (nza = 1; nza <= nnza; nza++) {
        j = (arow[nza] - firstrow + 1) + 1;
        rowstr[j] = rowstr[j] + 1;
    }

    rowstr[1] = 1;
    for (j = 2; j <= nrows+1; j++) {
        rowstr[j] = rowstr[j] + rowstr[j-1];
    }

    for (j = 0; j <= nrows-1; j++) {
        int ks = rowstr[j];
        int ke = rowstr[j+1] - 1;
        int len = ke - ks + 1;
        if (len > 0) {
#if defined(SPARSE_USE_RVV)
            int off = 0;
            while (off < len) {
                size_t vl = __riscv_vsetvl_e64m8((size_t)(len - off));
                vfloat64m8_t vz = __riscv_vfmv_v_f_f64m8(0.0, vl);
                __riscv_vse64_v_f64m8(&a[ks + off], vz, vl);
                off += (int)vl;
            }
#else
            for (k = ks; k <= ke; k++) {
                a[k] = 0.0;
            }
#endif
        }
    }

    for (nza = 1; nza <= nnza; nza++) {
        j = arow[nza] - firstrow + 1;
        k = rowstr[j];
        a[k] = aelt[nza];
        colidx[k] = acol[nza];
        rowstr[j] = rowstr[j] + 1;
    }

    for (j = nrows; j >= 1; j--) {
        rowstr[j+1] = rowstr[j];
    }
    rowstr[1] = 1;

    nza = 0;
#if defined(SPARSE_USE_RVV)
    {
        int idx = 1;
        while (idx <= n) {
            size_t vl = __riscv_vsetvl_e64m8((size_t)(n - idx + 1));
            vfloat64m8_t vz = __riscv_vfmv_v_f_f64m8(0.0, vl);
            __riscv_vse64_v_f64m8(&x[idx], vz, vl);
            idx += (int)vl;
        }
        idx = 1;
        while (idx <= n) {
            size_t vl = __riscv_vsetvl_e8m8((size_t)(n - idx + 1));
            vuint8m8_t vz_b = __riscv_vmv_v_x_u8m8((uint8_t)FALSE, vl);
            __riscv_vse8_v_u8m8((uint8_t *)&mark[idx], vz_b, vl);
            idx += (int)vl;
        }
    }
#else
    for (i = 1; i <= n; i++) {
        x[i] = 0.0;
        mark[i] = FALSE;
    }
#endif

    jajp1 = rowstr[1];
    for (j = 1; j <= nrows; j++) {
        nzrow = 0;

        for (k = jajp1; k < rowstr[j+1]; k++) {
            i = colidx[k];
            x[i] = x[i] + a[k];
            if (mark[i] == FALSE && x[i] != 0.0) {
                mark[i] = TRUE;
                nzrow = nzrow + 1;
                nzloc[nzrow] = i;
            }
        }

        for (k = 1; k <= nzrow; k++) {
            i = nzloc[k];
            mark[i] = FALSE;
            xi = x[i];
            x[i] = 0.0;
            if (xi != 0.0) {
                nza = nza + 1;
                a[nza] = xi;
                colidx[nza] = i;
            }
        }
        jajp1 = rowstr[j+1];
        rowstr[j+1] = nza + rowstr[1];
    }
}

static void sprnvc(
    int n,
    int nz,
    double v[],
    int iv[],
    int nzloc[],
    int mark[] )
{
    int nn1;
    int nzrow, nzv, ii, i;
    double vecelt, vecloc;

    nzv = 0;
    nzrow = 0;

    nn1 = 1;
    do {
        nn1 <<= 1;
    } while (nn1 < n);

    while (nzv < nz) {
        vecelt = randlc(&tran, amult);
        vecloc = randlc(&tran, amult);
        i = icnvrt(vecloc, nn1) + 1;

        if (__builtin_expect(i > n, 0)) continue;

        if (__builtin_expect(mark[i] == 0, 1)) {
            mark[i] = 1;
            ++nzrow;
            nzloc[nzrow] = i;
            ++nzv;
            v[nzv] = vecelt;
            iv[nzv] = i;
        }
    }

    for (ii = 1; ii <= nzrow; ++ii) {
        mark[nzloc[ii]] = 0;
    }
}

static void generate_gaussian_pairs(int np, double an, int k_offset,
                                    double *sx, double *sy, int *nthreads) {

    double t1, t2, t3, t4, x1, x2;
    int kk, i, ik, l, k;
    double qq[NQ];

    for (i = 0; i < NQ; i++) qq[i] = 0.0;

    for (k = 1; k <= np; k++) {
        kk = k_offset + k;
        t1 = S;
        t2 = an;

        for (i = 1; i <= 100; i++) {
            ik = kk / 2;
            if (2 * ik != kk) t3 = randlc(&t1, t2);
            if (ik == 0) break;
            t3 = randlc(&t2, t2);
            kk = ik;
        }

        if (TIMERS_ENABLED == TRUE) timer_start(3);
        vranlc(2 * NK, &t1, A, x - 1);
        if (TIMERS_ENABLED == TRUE) timer_stop(3);

        if (TIMERS_ENABLED == TRUE) timer_start(2);

        for (i = 0; i < NK; i++) {
            x1 = 2.0 * x[2 * i] - 1.0;
            x2 = 2.0 * x[2 * i + 1] - 1.0;
            t1 = pow2(x1) + pow2(x2);
            if (t1 <= 1.0) {
                t2 = sqrt(-2.0 * log(t1) / t1);
                t3 = (x1 * t2);
                t4 = (x2 * t2);
                l = max(fabs(t3), fabs(t4));
                qq[l] += 1.0;
                *sx = *sx + t3;
                *sy = *sy + t4;
            }
        }

        if (TIMERS_ENABLED == TRUE) timer_stop(2);
    }

    for (i = 0; i <= NQ - 1; i++) q[i] += qq[i];
    *nthreads = 1;
}

