                    }

                    {
                        vfloat64m1_t vt1v = __riscv_vle64_v_f64m1(buf_t1, vl);
                        vbool64_t vm = __riscv_vmfle_vf_f64m1_b64(vt1v, 1.0, vl);
                        (void)vm;
                    }

                    for (u = 0; u < vl; u++) {
