static void cffts1(int is, int d[3], dcomplex x[NZ][NY][NX],
		   dcomplex xout[NZ][NY][NX],
		   dcomplex y0[NX][FFTBLOCKPAD],
		   dcomplex y1[NX][FFTBLOCKPAD]) {

    int logd[3];
    int i, j, k, jj;

    for (i = 0; i < 3; i++) {
        logd[i] = ilog2(d[i]);
    }

    (void)y0;
    (void)y1;

    {
        dcomplex y0[NX][FFTBLOCKPAD];
        dcomplex y1[NX][FFTBLOCKPAD];

        for (k = 0; k < d[2]; k++) {
            for (jj = 0; jj <= d[1] - fftblock; jj += fftblock) {

                for (j = 0; j < fftblock; j++) {
                    dcomplex * __restrict dst = &y0[0][j];
                    dcomplex * __restrict src = &x[k][j + jj][0];

#if defined(__riscv_vector) && defined(__riscv_v_intrinsic)
                    {
                        size_t n = (size_t)d[0];
                        size_t idx = 0;
                        const ptrdiff_t stride = (ptrdiff_t)sizeof(dcomplex);
                        while (idx < n) {
                            size_t vl = __riscv_vsetvl_e64m1(n - idx);
                            vfloat64m1_t vr = __riscv_vlse64_v_f64m1(
                                (const double *)&src[idx].real, stride, vl);
                            vfloat64m1_t vi = __riscv_vlse64_v_f64m1(
                                (const double *)&src[idx].imag, stride, vl);
                            __riscv_vsse64_v_f64m1(
                                (double *)&dst[idx].real, stride, vr, vl);
                            __riscv_vsse64_v_f64m1(
                                (double *)&dst[idx].imag, stride, vi, vl);
                            idx += vl;
                        }
                    }
#else
                    for (i = 0; i < d[0]; i++) {
                        dst[i].real = src[i].real;
                        dst[i].imag = src[i].imag;
                    }
#endif
                }

                cfftz(is, logd[0], d[0], y0, y1);

                for (j = 0; j < fftblock; j++) {
                    dcomplex * __restrict src = &y0[0][j];
                    dcomplex * __restrict dst = &xout[k][j + jj][0];

#if defined(__riscv_vector) && defined(__riscv_v_intrinsic)
                    {
                        size_t n = (size_t)d[0];
                        size_t idx = 0;
                        const ptrdiff_t stride = (ptrdiff_t)sizeof(dcomplex);
                        while (idx < n) {
                            size_t vl = __riscv_vsetvl_e64m1(n - idx);
                            vfloat64m1_t vr = __riscv_vlse64_v_f64m1(
                                (const double *)&src[idx].real, stride, vl);
                            vfloat64m1_t vi = __riscv_vlse64_v_f64m1(
                                (const double *)&src[idx].imag, stride, vl);
                            __riscv_vsse64_v_f64m1(
                                (double *)&dst[idx].real, stride, vr, vl);
                            __riscv_vsse64_v_f64m1(
                                (double *)&dst[idx].imag, stride, vi, vl);
                            idx += vl;
                        }
                    }
#else
                    for (i = 0; i < d[0]; i++) {
                        dst[i].real = src[i].real;
                        dst[i].imag = src[i].imag;
                    }
#endif
                }
            }
        }
    }
}

static void cffts2(int is, int d[3], dcomplex x[NZ][NY][NX],
		   dcomplex xout[NZ][NY][NX],
		   dcomplex y0[NX][FFTBLOCKPAD],
		   dcomplex y1[NX][FFTBLOCKPAD]) {

    int logd[3];
    int i, j, k, ii;

    for (i = 0; i < 3; i++) {
	logd[i] = ilog2(d[i]);
    }

    {
        dcomplex y0_local[NX][FFTBLOCKPAD];
        dcomplex y1_local[NX][FFTBLOCKPAD];

        for (k = 0; k < d[2]; k++) {
            for (ii = 0; ii <= d[0] - fftblock; ii += fftblock) {

                for (j = 0; j < d[1]; j++) {
                    dcomplex *src = &x[k][j][ii];
                    dcomplex *dst = &y0_local[j][0];

                    for (i = 0; i < fftblock; i++) {
                        dst[i].real = src[i].real;
                        dst[i].imag = src[i].imag;
                    }
                }

                cfftz(is, logd[1], d[1], y0_local, y1_local);

                for (j = 0; j < d[1]; j++) {
                    dcomplex *src = &y0_local[j][0];
                    dcomplex *dst = &xout[k][j][ii];

                    for (i = 0; i < fftblock; i++) {
                        dst[i].real = src[i].real;
                        dst[i].imag = src[i].imag;
                    }
                }
            }
        }
    }
}

static void cffts3(int is, int d[3], dcomplex x[NZ][NY][NX],
		   dcomplex xout[NZ][NY][NX],
		   dcomplex y0[NX][FFTBLOCKPAD],
		   dcomplex y1[NX][FFTBLOCKPAD]) {

    int logd[3];
    int i, j, k, ii;

    for (i = 0; i < 3; i++) {
	logd[i] = ilog2(d[i]);
    }
    {
        dcomplex y0[NX][FFTBLOCKPAD];
        dcomplex y1[NX][FFTBLOCKPAD];

        for (j = 0; j < d[1]; j++) {
            for (ii = 0; ii <= d[0] - fftblock; ii += fftblock) {

                for (k = 0; k < d[2]; k++) {
                    dcomplex *src = &x[k][j][ii];
                    dcomplex *dst = &y0[k][0];

                    #pragma GCC ivdep
                    for (i = 0; i < fftblock; i++) {
                        dst[i].real = src[i].real;
                        dst[i].imag = src[i].imag;
                    }
                }

                cfftz(is, logd[2], d[2], y0, y1);

                for (k = 0; k < d[2]; k++) {
                    dcomplex *src = &y0[k][0];
                    dcomplex *dst = &xout[k][j][ii];

                    #pragma GCC ivdep
                    for (i = 0; i < fftblock; i++) {
                        dst[i].real = src[i].real;
                        dst[i].imag = src[i].imag;
                    }
                }
            }
        }
    }
}

static void cfftz (int is, int m, int n, dcomplex x[NX][FFTBLOCKPAD],
		   dcomplex y[NX][FFTBLOCKPAD]) {

    int i, j, l, mx;

    mx = (int)(u[0].real);
    if ((is != 1 && is != -1) || m < 1 || m > mx) {
	printf("CFFTZ: Either U has not been initialized, or else\n"
	       "one of the input parameters is invalid%5d%5d%5d\n",
	       is, m, mx);
	exit(1);
    }

    for (l = 1; l <= m; l += 2) {
        fftz2(is, l, m, n, fftblock, fftblockpad, u, x, y);
        if (l == m) break;
        fftz2(is, l + 1, m, n, fftblock, fftblockpad, u, y, x);
    }

    if (m & 1) {
        for (j = 0; j < n; ++j) {
            dcomplex *restrict xj = x[j];
            const dcomplex *restrict yj = y[j];

#if defined(__riscv_vector) && defined(__GNUC__)
            int rem = fftblock;
            int off = 0;
            long stride = (long)sizeof(dcomplex);
            while (rem > 0) {
                size_t vl;
                asm volatile ("vsetvli %0, %1, e64, m2, ta, ma"
                              : "=r"(vl)
                              : "r"(rem));

                asm volatile (
                    "vlse64.v v0, (%[src_re]), %[stride]\n\t"
                    "vlse64.v v1, (%[src_im]), %[stride]\n\t"
                    "vsse64.v v0, (%[dst_re]), %[stride]\n\t"
                    "vsse64.v v1, (%[dst_im]), %[stride]\n\t"
                    :
                    : [src_re] "r" (&yj[off].real),
                      [src_im] "r" (&yj[off].imag),
                      [dst_re] "r" (&xj[off].real),
                      [dst_im] "r" (&xj[off].imag),
                      [stride] "r" (stride)
                    : "v0", "v1", "memory"
                );

                off += (int)vl;
                rem -= (int)vl;
            }
#else
	    for (i = 0; i < fftblock; i++) {
		xj[i].real = yj[i].real;
		xj[i].imag = yj[i].imag;
	    }
#endif
	}
    }
}

static void checksum(int i, dcomplex u1[NZ][NY][NX], int d[3]) {
    int j, q, r, s, ierr;
    dcomplex chk, allchk;

    chk.real = 0.0;
    chk.imag = 0.0;

    {
        const int xs = xstart[0];
        const int xe = xend[0];
        const int ys = ystart[0];
        const int ye = yend[0];
        const int zs = zstart[0];
        const int ze = zend[0];

        const int xbase = 1 % NX;
        const int ybase = 3 % NY;
        const int zbase = 5 % NZ;

        int qmod = xbase;
        int rmod = ybase;
        int smod = zbase;

        for (j = 1; j <= 1024; ++j) {
            q = qmod + 1;
            if (q >= xs && q <= xe) {
                r = rmod + 1;
                if (r >= ys && r <= ye) {
                    s = smod + 1;
                    if (s >= zs && s <= ze) {
                        dcomplex v = u1[s - zs][r - ys][q - xs];
                        chk.real += v.real;
                        chk.imag += v.imag;
                    }
                }
            }

            qmod += 1;
            if (qmod >= NX) qmod -= NX;

            rmod += 3;
            while (rmod >= NY) rmod -= NY;

            smod += 5;
            while (smod >= NZ) smod -= NZ;
        }
    }

    {
        sums[i].real += chk.real;
        sums[i].imag += chk.imag;
    }
    {
        sums[i].real = sums[i].real / (double)(NTOTAL);
        sums[i].imag = sums[i].imag / (double)(NTOTAL);

        printf("T = %5d     Checksum = %22.12e %22.12e\n",
               i, sums[i].real, sums[i].imag);
    }
}

static void compute_indexmap(int indexmap[NZ][NY][NX], int d[3]) {

    int i, j, k, ii, ii2, jj, ij2, kk;
    double ap;

    {
        const int nx = dims[2][0];
        const int ny = dims[2][1];
        const int nz = dims[2][2];
        const int nx_half = NX / 2;
        const int ny_half = NY / 2;
        const int nz_half = NZ / 2;
        const int xoff = xstart[2] - 1 + nx_half;
        const int yoff = ystart[2] - 1 + ny_half;
        const int zoff = zstart[2] - 1 + nz_half;

        int kkbuf[NZ];

        for (k = 0; k < nz; k++) {
            kk = ((k + zoff) % NZ) - nz_half;
            kkbuf[k] = kk * kk;
        }

        for (i = 0; i < nx; i++) {
            ii = ((i + xoff) % NX) - nx_half;
            ii2 = ii * ii;

            for (j = 0; j < ny; j++) {
                jj = ((j + yoff) % NY) - ny_half;
                ij2 = jj * jj + ii2;

                for (k = 0; k < nz; k++) {
                    indexmap[k][j][i] = kkbuf[k] + ij2;
                }
            }
        }
    }

    ap = - 4.0 * ALPHA * PI * PI;

    ex[0] = 1.0;
    ex[1] = exp(ap);
    for (i = 2; i <= EXPMAX; i++) {
        ex[i] = ex[i - 1] * ex[1];
    }

}

static void compute_initial_conditions(dcomplex u0[NZ][NY][NX], int d[3]) {

    int k;
    double x0, start, an, dummy;
    static double tmp[NX*2*MAXDIM+1];
    int j, t;
    const int ny = dims[0][1];
    const int nz = dims[0][2];

    (void)d;

    start = SEED;

    ipow46(A, (zstart[0]-1)*2*NX*NY + (ystart[0]-1)*2*NX, &an);
    dummy = randlc(&start, an);
    ipow46(A, 2*NX*NY, &an);

    for (k = 0; k < nz; k++) {
        x0 = start;
        vranlc(2 * NX * ny, &x0, A, tmp);

        t = 1;
        for (j = 0; j < ny; j++) {
            dcomplex *dst = &u0[k][j][0];
            double *src = &tmp[t];
            int i = 0;

            for (; i + 7 < NX; i += 8) {
                dst[i + 0].real = src[0];
                dst[i + 0].imag = src[1];
                dst[i + 1].real = src[2];
                dst[i + 1].imag = src[3];
                dst[i + 2].real = src[4];
                dst[i + 2].imag = src[5];
                dst[i + 3].real = src[6];
                dst[i + 3].imag = src[7];
                dst[i + 4].real = src[8];
                dst[i + 4].imag = src[9];
                dst[i + 5].real = src[10];
                dst[i + 5].imag = src[11];
                dst[i + 6].real = src[12];
                dst[i + 6].imag = src[13];
                dst[i + 7].real = src[14];
                dst[i + 7].imag = src[15];
                src += 16;
            }
            for (; i + 3 < NX; i += 4) {
                dst[i + 0].real = src[0];
                dst[i + 0].imag = src[1];
                dst[i + 1].real = src[2];
                dst[i + 1].imag = src[3];
                dst[i + 2].real = src[4];
                dst[i + 2].imag = src[5];
                dst[i + 3].real = src[6];
                dst[i + 3].imag = src[7];
                src += 8;
            }
            for (; i < NX; i++) {
                dst[i].real = src[0];
                dst[i].imag = src[1];
                src += 2;
            }

            t += 2 * NX;
        }

        if (k != nz) dummy = randlc(&start, an);
    }
}

static void evolve(dcomplex u0[NZ][NY][NX], dcomplex u1[NZ][NY][NX],
		   int t, int indexmap[NZ][NY][NX], int d[3]) {

    int i, j, k;
    const int d0 = d[0];
    const int d1 = d[1];
    const int d2 = d[2];

#if defined(__riscv_vector)
    for (k = 0; k < d2; k++) {
        for (j = 0; j < d1; j++) {
            dcomplex * restrict u1_row = &u1[k][j][0];
            const dcomplex * restrict u0_row = &u0[k][j][0];
            const int * restrict im_row = &indexmap[k][j][0];

            i = 0;
            while (i < d0) {
                size_t vl = __riscv_vsetvl_e32m1((size_t)(d0 - i));
                const int *idxp = im_row + i;

                vint32m1_t vidx = __riscv_vle32_v_i32m1(idxp, vl);

                vfloat64m2_t vr0 = __riscv_vundefined_f64m2();
                vfloat64m2_t vi0 = __riscv_vundefined_f64m2();
                vfloat64m2_t ver = __riscv_vundefined_f64m2();
                vfloat64m2_t vei = __riscv_vundefined_f64m2();

                size_t n = vl;
                size_t lane = 0;
                while (n--) {
                    dcomplex a = u0_row[i + (int)lane];
                    dcomplex b = ex[t * idxp[lane]];
                    vr0 = __riscv_vfmv_s_f_f64m2(vr0, a.real);
                    vi0 = __riscv_vfmv_s_f_f64m2(vi0, a.imag);
                    ver = __riscv_vfmv_s_f_f64m2(ver, b.real);
                    vei = __riscv_vfmv_s_f_f64m2(vei, b.imag);
                    if (++lane < vl) {
                        vr0 = __riscv_vslideup_vx_f64m2(vr0, vr0, 1, vl);
                        vi0 = __riscv_vslideup_vx_f64m2(vi0, vi0, 1, vl);
                        ver = __riscv_vslideup_vx_f64m2(ver, ver, 1, vl);
                        vei = __riscv_vslideup_vx_f64m2(vei, vei, 1, vl);
                    }
                }

                vfloat64m2_t rr = __riscv_vfsub_vv_f64m2(
                    __riscv_vfmul_vv_f64m2(vr0, ver, vl),
                    __riscv_vfmul_vv_f64m2(vi0, vei, vl),
                    vl);
                vfloat64m2_t ri = __riscv_vfadd_vv_f64m2(
                    __riscv_vfmul_vv_f64m2(vr0, vei, vl),
                    __riscv_vfmul_vv_f64m2(vi0, ver, vl),
                    vl);

                double tr[32];
                double ti[32];
                __riscv_vse64_v_f64m2(tr, rr, vl);
                __riscv_vse64_v_f64m2(ti, ri, vl);

                for (lane = 0; lane < vl; lane++) {
                    u1_row[i + (int)lane].real = tr[lane];
                    u1_row[i + (int)lane].imag = ti[lane];
                }

                i += (int)vl;
            }
        }
    }
#else
    for (k = 0; k < d2; k++) {
	for (j = 0; j < d1; j++) {
            for (i = 0; i < d0; i++) {
	      crmul(u1[k][j][i], u0[k][j][i], ex[t*indexmap[k][j][i]]);
	    }
	}
    }
#endif
}

static void fft(int dir, dcomplex x1[NZ][NY][NX], dcomplex x2[NZ][NY][NX]) {

    dcomplex y0[NX][FFTBLOCKPAD];
    dcomplex y1[NX][FFTBLOCKPAD];

#if defined(__GNUC__) || defined(__clang__)
    __builtin_prefetch((const void *)&x1[0][0][0], 0, 3);
    __builtin_prefetch((const void *)&x2[0][0][0], 1, 3);
    __builtin_prefetch((const void *)&y0[0][0], 1, 3);
    __builtin_prefetch((const void *)&y1[0][0], 1, 3);
#endif

#if defined(__riscv) && defined(__GNUC__)
    __asm__ __volatile__("" : : "r"(x1), "r"(x2), "r"(y0), "r"(y1) : "memory");
#endif

    if (__builtin_expect(dir == 1, 1)) {
        cffts1(1, dims[0], x1, x1, y0, y1);
        cffts2(1, dims[1], x1, x1, y0, y1);
        cffts3(1, dims[2], x1, x2, y0, y1);
    } else {
        cffts3(-1, dims[2], x1, x1, y0, y1);
        cffts2(-1, dims[1], x1, x1, y0, y1);
        cffts1(-1, dims[0], x1, x2, y0, y1);
    }
}

static void fft_init (int n) {

    int m, nu, ku, i, j, ln;
    double t, ti;

    nu = n;
    m = ilog2(n);
    u[0].real = (double)m;
    u[0].imag = 0.0;
    ku = 1;
    ln = 1;

    for (j = 1; j <= m; j++) {
        t = PI / (double)ln;

        for (i = 0; i < ln; i++) {
            ti = (double)i * t;
            u[i + ku].real = cos(ti);
            u[i + ku].imag = sin(ti);
        }

        ku += ln;
        ln <<= 1;
    }
}

static void fftz2 (int is, int l, int m, int n, int ny, int ny1,
		   dcomplex u[NX], dcomplex x[NX][FFTBLOCKPAD],
		   dcomplex y[NX][FFTBLOCKPAD]) {

    int k, n1, li, lj, lk, ku, i, j, i11, i12, i21, i22;
    dcomplex u1;

    (void)ny1;

    n1 = n / 2;
    if (l - 1 == 0) {
        lk = 1;
    } else {
        lk = 2 << ((l - 1) - 1);
    }
    if (m - l == 0) {
        li = 1;
    } else {
        li = 2 << ((m - l) - 1);
    }
    lj = 2 * lk;
    ku = li;

    for (i = 0; i < li; i++) {
        i11 = i * lk;
        i12 = i11 + n1;
        i21 = i * lj;
        i22 = i21 + lk;

        u1.real = u[ku + i].real;
        if (is >= 1) {
            u1.imag = u[ku + i].imag;
        } else {
            u1.imag = -u[ku + i].imag;
        }

        for (k = 0; k < lk; k++) {
            dcomplex *x1 = &x[i11 + k][0];
            dcomplex *x2 = &x[i12 + k][0];
            dcomplex *y1 = &y[i21 + k][0];
            dcomplex *y2 = &y[i22 + k][0];
            const double ur = u1.real;
            const double ui = u1.imag;

            for (j = 0; j < ny; j++) {
                double x11real = x1[j].real;
                double x11imag = x1[j].imag;
                double x21real = x2[j].real;
                double x21imag = x2[j].imag;
                double dr = x11real - x21real;
                double di = x11imag - x21imag;

                y1[j].real = x11real + x21real;
                y1[j].imag = x11imag + x21imag;
                y2[j].real = ur * dr - ui * di;
                y2[j].imag = ur * di + ui * dr;
            }
        }
    }
}

int main(int argc, char **argv) {

    int i, ierr;

    static dcomplex u0[NZ][NY][NX];
    static dcomplex pad1[3];
    static dcomplex u1[NZ][NY][NX];
    static dcomplex pad2[3];
    static dcomplex u2[NZ][NY][NX];
    static dcomplex pad3[3];
    static int indexmap[NZ][NY][NX];

    int iter;
    int nthreads = 1;
    double total_time, mflops;
    boolean verified;
    char class;

    const int timers_enabled = (TIMERS_ENABLED == TRUE);

    for (i = 0; i < T_MAX; ++i) {
        timer_clear(i);
    }

    setup();

    compute_indexmap(indexmap, dims[2]);
    compute_initial_conditions(u1, dims[0]);
    fft_init(dims[0][0]);
    fft(1, u1, u0);

    for (i = 0; i < T_MAX; ++i) {
        timer_clear(i);
    }

    timer_start(T_TOTAL);

    if (timers_enabled) {
        timer_start(T_SETUP);
    }

    compute_indexmap(indexmap, dims[2]);
    compute_initial_conditions(u1, dims[0]);
    fft_init(dims[0][0]);

    if (timers_enabled) {
        timer_stop(T_SETUP);
        timer_start(T_FFT);
    }

    fft(1, u1, u0);

    if (timers_enabled) {
        timer_stop(T_FFT);
    }

    for (iter = 1; iter <= niter; ++iter) {
        if (timers_enabled) {
            timer_start(T_EVOLVE);
        }

        evolve(u0, u1, iter, indexmap, dims[0]);

        if (timers_enabled) {
            timer_stop(T_EVOLVE);
            timer_start(T_FFT);
        }

        fft(-1, u1, u2);

        if (timers_enabled) {
            timer_stop(T_FFT);
            timer_start(T_CHECKSUM);
        }

        checksum(iter, u2, dims[0]);

        if (timers_enabled) {
            timer_stop(T_CHECKSUM);
        }
    }

    verify(NX, NY, NZ, niter, &verified, &class);

    {
#if defined(_OPENMP)
        nthreads = omp_get_num_threads();
#endif
    }

    timer_stop(T_TOTAL);
    total_time = timer_read(T_TOTAL);

    if (total_time != 0.0) {
        const double ntotal_d = (double)(NTOTAL);
        const double log_ntotal = log(ntotal_d);
        const double term1 = 14.8157 + 7.19641 * log_ntotal;
        const double term2 = 5.23518 + 7.21113 * log_ntotal;
        mflops = 1.0e-6 * ntotal_d * (term1 + term2 * niter) / total_time;
    } else {
        mflops = 0.0;
    }

    c_print_results("FT", class, NX, NY, NZ, niter, nthreads,
                    total_time, mflops, "          floating point", verified,
                    NPBVERSION, COMPILETIME,
                    CS1, CS2, CS3, CS4, CS5, CS6, CS7);

    if (timers_enabled) {
        print_timers();
    }
}

static void comm3(double ***u, int n1, int n2, int n3, int kk) {
    int i1, i2, i3;
    (void)kk;

    for (i3 = 1; i3 < n3 - 1; i3++) {
        double **u_i3 = u[i3];

        for (i2 = 1; i2 < n2 - 1; i2++) {
            double *row = u_i3[i2];
            row[n1 - 1] = row[1];
            row[0] = row[n1 - 2];
        }

        {
            double *dst_hi = u_i3[n2 - 1];
            double *src_hi = u_i3[1];
            double *dst_lo = u_i3[0];
            double *src_lo = u_i3[n2 - 2];
            for (i1 = 0; i1 < n1; i1++) {
                dst_hi[i1] = src_hi[i1];
                dst_lo[i1] = src_lo[i1];
            }
        }
    }

    for (i2 = 0; i2 < n2; i2++) {
        double *dst_hi = u[n3 - 1][i2];
        double *src_hi = u[1][i2];
        double *dst_lo = u[0][i2];
        double *src_lo = u[n3 - 2][i2];
        for (i1 = 0; i1 < n1; i1++) {
            dst_hi[i1] = src_hi[i1];
            dst_lo[i1] = src_lo[i1];
        }
    }
}

