	c[2] =  -1.0/61.0;
	c[3] =   0.0;
    }

    lb = 1;

    setup(&n1,&n2,&n3,lt);

    u = (double ****)malloc((lt+1)*sizeof(double ***));
    for (l = lt; l >=1; l--) {
	u[l] = (double ***)malloc(m3[l]*sizeof(double **));
	for (k = 0; k < m3[l]; k++) {
	    u[l][k] = (double **)malloc(m2[l]*sizeof(double *));
	    for (j = 0; j < m2[l]; j++) {
		u[l][k][j] = (double *)malloc(m1[l]*sizeof(double));
	    }
	}
    }
    v = (double ***)malloc(m3[lt]*sizeof(double **));
    for (k = 0; k < m3[lt]; k++) {
	v[k] = (double **)malloc(m2[lt]*sizeof(double *));
	for (j = 0; j < m2[lt]; j++) {
	    v[k][j] = (double *)malloc(m1[lt]*sizeof(double));
	}
    }
    r = (double ****)malloc((lt+1)*sizeof(double ***));
    for (l = lt; l >=1; l--) {
	r[l] = (double ***)malloc(m3[l]*sizeof(double **));
	for (k = 0; k < m3[l]; k++) {
	    r[l][k] = (double **)malloc(m2[l]*sizeof(double *));
	    for (j = 0; j < m2[l]; j++) {
		r[l][k][j] = (double *)malloc(m1[l]*sizeof(double));
	    }
	}
    }

    zero3(u[lt],n1,n2,n3);
    zran3(v,n1,n2,n3,nx[lt],ny[lt],lt);

    norm2u3(v,n1,n2,n3,&rnm2,&rnmu,nx[lt],ny[lt],nz[lt]);

    printf(" Size: %3dx%3dx%3d (class %1c)\n",
	   nx[lt], ny[lt], nz[lt], Class);
    printf(" Iterations: %3d\n", nit);

    resid(u[lt],v,r[lt],n1,n2,n3,a,lt);
    norm2u3(r[lt],n1,n2,n3,&rnm2,&rnmu,nx[lt],ny[lt],nz[lt]);

    mg3P(u,v,r,a,c,n1,n2,n3,lt);
    resid(u[lt],v,r[lt],n1,n2,n3,a,lt);

    setup(&n1,&n2,&n3,lt);

    zero3(u[lt],n1,n2,n3); 

    zran3(v,n1,n2,n3,nx[lt],ny[lt],lt);


    timer_stop(T_INIT);
    timer_start(T_BENCH);

    resid(u[lt],v,r[lt],n1,n2,n3,a,lt);
    norm2u3(r[lt],n1,n2,n3,&rnm2,&rnmu,nx[lt],ny[lt],nz[lt]);

    for ( it = 1; it <= nit; it++) {
	mg3P(u,v,r,a,c,n1,n2,n3,lt);
	resid(u[lt],v,r[lt],n1,n2,n3,a,lt);
    }
    norm2u3(r[lt],n1,n2,n3,&rnm2,&rnmu,nx[lt],ny[lt],nz[lt]);

{   
#if defined(_OPENMP)
  nthreads = omp_get_num_threads();
#endif 
} 

    timer_stop(T_BENCH);
    t = timer_read(T_BENCH);
    tinit = timer_read(T_INIT);

    verified = FALSE;
    verify_value = 0.0;

    printf(" Initialization time: %15.3f seconds\n", tinit);
    printf(" Benchmark completed\n");

    if (Class != 'U') {
	if (Class == 'S') {
            verify_value = 0.530770700573e-04;
	} else if (Class == 'W') {
            verify_value = 0.250391406439e-17;  

	} else if (Class == 'A') {
            verify_value = 0.2433365309e-5;
        } else if (Class == 'B') {
            verify_value = 0.180056440132e-5;
        } else if (Class == 'C') {
            verify_value = 0.570674826298e-06;
	}

	if ( fabs( rnm2 - verify_value ) <= epsilon ) {
            verified = TRUE;
	    printf(" VERIFICATION SUCCESSFUL\n");
	    printf(" L2 Norm is %20.12e\n", rnm2);
	    printf(" Error is   %20.12e\n", rnm2 - verify_value);
	} else {
            verified = FALSE;
	    printf(" VERIFICATION FAILED\n");
	    printf(" L2 Norm is             %20.12e\n", rnm2);
	    printf(" The correct L2 Norm is %20.12e\n", verify_value);
	}
    } else {
	verified = FALSE;
	printf(" Problem size unknown\n");
	printf(" NO VERIFICATION PERFORMED\n");
    }

    if ( t != 0.0 ) {
	int nn = nx[lt]*ny[lt]*nz[lt];
	mflops = 58.*nit*nn*1.0e-6 / t;
    } else {
	mflops = 0.0;
    }

    c_print_results("MG", Class, nx[lt], ny[lt], nz[lt], 
		    nit, 1, t, mflops, "          floating point", 
		    verified, NPBVERSION, COMPILETIME,
		    CS1, CS2, CS3, CS4, CS5, CS6, CS7);

    return 0;
}

static void mg3P(double ****u, double ***v, double ****r, double a[4],
		 double c[4], int n1, int n2, int n3, int k) {

    int j;

    for (k = lt; k >= lb+1; k--) {
	j = k-1;
	rprj3(r[k], m1[k], m2[k], m3[k],
	      r[j], m1[j], m2[j], m3[j], k);
    }

    k = lb;

    zero3(u[k], m1[k], m2[k], m3[k]);
    psinv(r[k], u[k], m1[k], m2[k], m3[k], c, k);

    for (k = lb+1; k <= lt-1; k++) {
	j = k-1;

	zero3(u[k], m1[k], m2[k], m3[k]);
	interp(u[j], m1[j], m2[j], m3[j],
	       u[k], m1[k], m2[k], m3[k], k);

	resid(u[k], r[k], r[k], m1[k], m2[k], m3[k], a, k);

	psinv(r[k], u[k], m1[k], m2[k], m3[k], c, k);
    }

    j = lt - 1;
    k = lt;
    interp(u[j], m1[j], m2[j], m3[j], u[lt], n1, n2, n3, k);
    resid(u[lt], v, r[lt], n1, n2, n3, a, k);
    psinv(r[lt], u[lt], n1, n2, n3, c, k);
}

static void norm2u3(double ***r, int n1, int n2, int n3,
		    double *rnm2, double *rnmu, int nx, int ny, int nz) {

    double s = 0.0;
    int i3, i2, i1, n;
    double a = 0.0, tmp = 0.0;

    n = nx * ny * nz;

    for (i3 = 1; i3 < n3 - 1; i3++) {
        double **r3 = r[i3];
        for (i2 = 1; i2 < n2 - 1; i2++) {
            double *row = r3[i2];
            for (i1 = 1; i1 < n1 - 1; i1++) {
                double v = row[i1];
                s = s + v * v;
                a = fabs(v);
                if (a > tmp) tmp = a;
            }
        }
    }
    *rnmu = tmp;
    *rnm2 = sqrt(s / (double)n);
}

static void psinv( double ***r, double ***u, int n1, int n2, int n3,
		   double c[4], int k) {

    int i3, i2, i1;
    double r1[M], r2[M];

    for (i3 = 1; i3 < n3-1; i3++) {
	for (i2 = 1; i2 < n2-1; i2++) {
            double *r_i_jm1   = r[i3][i2-1];
            double *r_i_jp1   = r[i3][i2+1];
            double *r_im1_j   = r[i3-1][i2];
            double *r_ip1_j   = r[i3+1][i2];
            double *r_im1_jm1 = r[i3-1][i2-1];
            double *r_im1_jp1 = r[i3-1][i2+1];
            double *r_ip1_jm1 = r[i3+1][i2-1];
            double *r_ip1_jp1 = r[i3+1][i2+1];
            double *r_i_j     = r[i3][i2];
            double *u_i_j     = u[i3][i2];

            for (i1 = 0; i1 < n1; i1++) {
		r1[i1] = r_i_jm1[i1] + r_i_jp1[i1]
		    + r_im1_j[i1] + r_ip1_j[i1];
		r2[i1] = r_im1_jm1[i1] + r_im1_jp1[i1]
		    + r_ip1_jm1[i1] + r_ip1_jp1[i1];
	    }
            for (i1 = 1; i1 < n1-1; i1++) {
		u_i_j[i1] = u_i_j[i1]
		    + c[0] * r_i_j[i1]
		    + c[1] * ( r_i_j[i1-1] + r_i_j[i1+1]
			       + r1[i1] )
		    + c[2] * ( r2[i1] + r1[i1-1] + r1[i1+1] );

	    }
	}
    }

    comm3(u,n1,n2,n3,k);

    if (debug_vec[0] >= 1 ) {
	rep_nrm(u,n1,n2,n3,"   psinv",k);
    }

    if ( debug_vec[3] >= k ) {
	showall(u,n1,n2,n3);
    }
}

static void resid( double ***u, double ***v, double ***r,
		   int n1, int n2, int n3, double a[4], int k ) {

    int i3, i2, i1;
    double u1[M], u2[M];

    for (i3 = 1; i3 < n3-1; i3++) {
        double **ui3m1 = u[i3-1];
        double **ui3   = u[i3];
        double **ui3p1 = u[i3+1];
        double **vi3   = v[i3];
        double **ri3   = r[i3];

	for (i2 = 1; i2 < n2-1; i2++) {
            double *u_i2m1   = ui3[i2-1];
            double *u_i2     = ui3[i2];
            double *u_i2p1   = ui3[i2+1];
            double *u_m1_i2  = ui3m1[i2];
            double *u_p1_i2  = ui3p1[i2];
            double *u_m1_m1  = ui3m1[i2-1];
            double *u_m1_p1  = ui3m1[i2+1];
            double *u_p1_m1  = ui3p1[i2-1];
            double *u_p1_p1  = ui3p1[i2+1];
            double *v_i2     = vi3[i2];
            double *r_i2     = ri3[i2];

            for (i1 = 0; i1 < n1; i1++) {
		u1[i1] = u_i2m1[i1] + u_i2p1[i1]
		       + u_m1_i2[i1] + u_p1_i2[i1];
		u2[i1] = u_m1_m1[i1] + u_m1_p1[i1]
		       + u_p1_m1[i1] + u_p1_p1[i1];
	    }
	    for (i1 = 1; i1 < n1-1; i1++) {
		r_i2[i1] = v_i2[i1]
		    - a[0] * u_i2[i1]

		- a[2] * ( u2[i1] + u1[i1-1] + u1[i1+1] )
		      - a[3] * ( u2[i1-1] + u2[i1+1] );
	    }
	}
    }

    comm3(r,n1,n2,n3,k);

    if (debug_vec[0] >= 1 ) {
	rep_nrm(r,n1,n2,n3,"   resid",k);
    }

    if ( debug_vec[2] >= k ) {
	showall(r,n1,n2,n3);
    }
}

static void rprj3( double ***r, int m1k, int m2k, int m3k,
		   double ***s, int m1j, int m2j, int m3j, int k ) {

    int j3, j2, j1, i3, i2, i1, d1, d2, d3;
    double x1[M], y1[M], x2, y2;

    if (m1k == 3) {
        d1 = 2;
    } else {
        d1 = 1;
    }

    if (m2k == 3) {
        d2 = 2;
    } else {
        d2 = 1;
    }

    if (m3k == 3) {
        d3 = 2;
    } else {
        d3 = 1;
    }

    for (j3 = 1; j3 < m3j-1; j3++) {
        i3 = 2*j3-d3;

        for (j2 = 1; j2 < m2j-1; j2++) {
            double *r_i3     = r[i3];
            double *r_i3p1_0;
            double *r_i3p2_0;
            i2 = 2*j2-d2;

            {
                double *r_i3_p1_i2   = r[i3+1][i2];
                double *r_i3_p1_i2p2 = r[i3+1][i2+2];
                double *r_i3_i2p1    = r_i3[i2+1];
                double *r_i3p2_i2p1  = r[i3+2][i2+1];
                double *r_i3_i2      = r_i3[i2];
                double *r_i3p2_i2    = r[i3+2][i2];
                double *r_i3_i2p2    = r_i3[i2+2];
                double *r_i3p2_i2p2  = r[i3+2][i2+2];
                double *r_c          = r[i3+1][i2+1];
                double *s_j3_j2      = s[j3][j2];

                for (j1 = 1; j1 < m1j; j1++) {
                    i1 = 2*j1-d1;

                    x1[i1] = r_i3_p1_i2[i1] + r_i3_p1_i2p2[i1]
                           + r_i3_i2p1[i1] + r_i3p2_i2p1[i1];
                    y1[i1] = r_i3_i2[i1] + r_i3p2_i2[i1]
                           + r_i3_i2p2[i1] + r_i3p2_i2p2[i1];
                }

                for (j1 = 1; j1 < m1j-1; j1++) {
                    i1 = 2*j1-d1;

                    y2 = r_i3_i2[i1+1] + r_i3p2_i2[i1+1]
                       + r_i3_i2p2[i1+1] + r_i3p2_i2p2[i1+1];
                    x2 = r_i3_p1_i2[i1+1] + r_i3_p1_i2p2[i1+1]
                       + r_i3_i2p1[i1+1] + r_i3p2_i2p1[i1+1];
                    s_j3_j2[j1] =
                        0.5 * r_c[i1+1]
                        + 0.25 * ( r_c[i1] + r_c[i1+2] + x2)
                        + 0.125 * ( x1[i1] + x1[i1+2] + y2)
                        + 0.0625 * ( y1[i1] + y1[i1+2] );
                }
            }
        }
    }
    comm3(s,m1j,m2j,m3j,k-1);

    if (debug_vec[0] >= 1 ) {
        rep_nrm(s,m1j,m2j,m3j,"   rprj3",k-1);
    }

    if (debug_vec[4] >= k ) {
        showall(s,m1j,m2j,m3j);
    }
}

static void zero3(double ***z, int n1, int n2, int n3) {

    int i1, i2, i3;
    for (i3 = 0; i3 < n3; i3++) {
        for (i2 = 0; i2 < n2; i2++) {
            for (i1 = 0; i1 < n1; i1++) {
                z[i3][i2][i1] = 0.0;
            }
        }
    }
}
